task.starter_code:
// Платформа задаёт:
// const students = [
//     { name: "Анна", score: 92 },
//     { name: "Тимур", score: 78 },
//     { name: "Лола", score: 65 },
//     { name: "Сардор", score: 95 },
// ];
// Функции проверят и на других массивах, в том числе пустом.

// 1. getAverage(list) - reduce, Math.round, пустой массив → 0

// 2. getExcellentNames(list) - filter + map, имена с баллом от 90

// 3. findStudent(list, name) - find

// 4. addStudent(list, name, score) - новый массив через ...

task.setup:
const students = [
    { name: "Анна", score: 92 },
    { name: "Тимур", score: 78 },
    { name: "Лола", score: 65 },
    { name: "Сардор", score: 95 },
];

task.solution:
function getAverage(list) {
    if (list.length === 0) {
        return 0;
    }
    const total = list.reduce((sum, student) => sum + student.score, 0);
    return Math.round(total / list.length);
}

function getExcellentNames(list) {
    return list
        .filter((student) => student.score >= 90)
        .map((student) => student.name);
}

function findStudent(list, name) {
    return list.find((student) => student.name === name);
}

function addStudent(list, name, score) {
    return [...list, { name, score }];
}

console.log(getAverage(students), getExcellentNames(students));

